-- Read-only C.3 installation audit. PASS is not runtime, account or provider acceptance.
with checks as (
  select 'Mission table and RLS' as check_name, exists(select 1 from pg_class where oid=to_regclass('public.agent_missions') and relrowsecurity) as passed
  union all select 'Mission client writes closed', to_regclass('public.agent_missions') is not null and not exists(
    select 1 from unnest(array['anon','authenticated']) r where has_table_privilege(r,to_regclass('public.agent_missions'),'INSERT,UPDATE,DELETE,TRUNCATE'))
  union all select 'Mission owner-only reads', (select count(*)=1 and bool_and(cmd='SELECT' and qual like '%auth.uid()%user_id%') from pg_policies where schemaname='public' and tablename='agent_missions')
  union all select 'Mission owner cascades', (select count(*)=2 from pg_constraint where conrelid=to_regclass('public.agent_missions') and contype='f' and confdeltype='c' and confrelid in(to_regclass('public.projects'),to_regclass('auth.users')))
  union all select 'Run mission-owner composite cascade', exists(select 1 from pg_constraint where conrelid=to_regclass('public.agent_runs') and confrelid=to_regclass('public.agent_missions') and contype='f' and confdeltype='c' and cardinality(conkey)=3)
  union all select 'Daily execution identity installed', exists(select 1 from pg_indexes where schemaname='public' and tablename='agent_runs' and indexname='agent_runs_mission_daily_key' and indexdef like '%UNIQUE%mission_id, mission_revision, mission_day%')
  union all select 'Mission RPCs server-only', (select count(*)=4 and bool_and(not p.prosecdef and not has_function_privilege('anon',p.oid,'execute') and not has_function_privilege('authenticated',p.oid,'execute') and has_function_privilege('service_role',p.oid,'execute')) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('save_agent_mission','pause_agent_mission','reserve_agent_mission_run','transition_agent_mission_run'))
  union all select 'Shared budget and retention preserved', exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='reserve_agent_mission_run' and p.prosrc like '%public.reserve_agent_run(%' and p.prosrc like '%updated_at=prior_updated_at%')
  union all select 'Authorization expiry fenced', exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='transition_agent_mission_run' and p.prosrc like '%m.expires_at<=now()%') and exists(select 1 from pg_constraint where conrelid=to_regclass('public.agent_missions') and pg_get_constraintdef(oid) like '%expires_at%authorized_at%30 days%')
  union all select 'Mission export marker and deletion', exists(select 1 from information_schema.columns where table_schema='public' and table_name='entitlements' and column_name='mission_data_initialized' and data_type='boolean' and is_nullable='NO') and exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='delete_postbeacon_user_data' and p.prosrc like '%delete from public.agent_missions%')
)
select check_name,case when passed then 'PASS' else 'FAIL' end as status from checks;
